options.styles:
.header {
  display: flex;
  align-items: center;
  width: 100%;
  height: 60px;
  background: #7eb4e2;
}

.arrow-pointer {
  display: flex;
  align-items: center;
  width: 100%;
  height: 50px;
  background: #32557f;
  position: relative;
  margin: auto;
  margin-right: 25px;

  &:after {
    content: '';
    position: absolute;
    left: 0;
    bottom: 0;
    width: 0;
    height: 0;
    border-left: 25px solid #7eb4e2;
    border-top: 25px solid transparent;
    border-bottom: 25px solid transparent;
  }

  &:before {
    content: '';
    position: absolute;
    right: -25px;
    bottom: 0;
    width: 0;
    height: 0;
    border-left: 25px solid #32557f;
    border-top: 25px solid transparent;
    border-bottom: 25px solid transparent;
  }
}

.header-text {
  font-size: x-large;
  padding: 0;
  margin: auto;
  padding-left: 25px;
}

