.body {
  display: flex;
  flex-wrap: wrap;
  background: #7eb4e2;
  padding: 5px;
  margin: 0;
  width: 100%;
}

.OK-box {
  flex: 1 0 15%;
  height: 6vh;
  width: 100%;
  background: green;
  box-sizing: border-box;
}

